FUNCTION_BLOCK FB_S03
VAR_INPUT
    DoorSwitch : BOOL;
    ZoneAOccupied : BOOL;
    ZoneBOccupied : BOOL;
    ResetBtn : BOOL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    DriveA_Run : BOOL := FALSE;
    DriveB_Run : BOOL := FALSE;
    AlarmLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    FirstScan : BOOL := TRUE;
    PreviousDoor : BOOL := FALSE;
    PreviousReset : BOOL := FALSE;
    DoorRise : BOOL;
    ResetRise : BOOL;
    ResetConfirmed : BOOL := TRUE;
    BStopPending : BOOL := FALSE;
    BDelayScans : UINT := UINT#0;
END_VAR

(*
    待审问题，保留而不补造接口或需求：
    1. 需求包含“启动按钮”和“B 区动作完成”，接口均未提供。
       ResetBtn 仅用于确认，不作为启动按钮。
       ZoneAOccupied、ZoneBOccupied 未定义控制语义，不作为动作完成信号。
       本实现不自行启动驱动；B 区仅实现已有运行状态的限时保持。
       因此，完整启动和动作完成提前停止功能待接口澄清。
    2. C10 要求上电首周期无报警，与上电时门开或急停必须报警冲突。
       输出声明保留给定初值；执行扫描时安全报警优先。
    3. C1b 允许 [0,1] 周期，原文/K1 要求同周期；采用同周期停止。
    4. 待复位状态与门开、急停状态重叠时，采用：
       急停 > 门开 > 待复位 > 正常。
    每次调用为 20 ms。开门检测周期计数为零；
    随后的第 25 次调用达到 500 ms。
    未声称经过编译或逐周期功能验证。
*)

ResetRise := ResetBtn AND NOT PreviousReset;
DoorRise := DoorSwitch AND NOT PreviousDoor;

IF FirstScan THEN
    DriveA_Run := FALSE;
    DriveB_Run := FALSE;
    BStopPending := FALSE;
    BDelayScans := UINT#0;
    ResetConfirmed := TRUE;
    FirstScan := FALSE;
END_IF;

IF NOT EStop_NC THEN
    (* 急停无条件覆盖分级停机、复位和保持。 *)
    DriveA_Run := FALSE;
    DriveB_Run := FALSE;
    ResetConfirmed := FALSE;
    BStopPending := FALSE;
    BDelayScans := UINT#0;

ELSE
    IF DoorSwitch THEN
        DriveA_Run := FALSE;
        ResetConfirmed := FALSE;
    END_IF;

    IF DoorRise THEN
        (* 只能保持开门前已经运行的 B 区，不能因开门启动。 *)
        BStopPending := DriveB_Run;
        BDelayScans := UINT#0;
    ELSIF BStopPending THEN
        IF BDelayScans < UINT#25 THEN
            BDelayScans := BDelayScans + UINT#1;
        END_IF;
    END_IF;

    (* 门关闭不能自行撤销已经触发的限时停止。 *)
    IF BStopPending THEN
        IF BDelayScans >= UINT#25 THEN
            DriveB_Run := FALSE;
            BStopPending := FALSE;
        END_IF;
    END_IF;

    IF DoorSwitch AND NOT BStopPending THEN
        DriveB_Run := FALSE;
    END_IF;

    (* 仅在门已关闭且急停正常时接收复位上升沿。 *)
    IF NOT DoorSwitch AND ResetRise THEN
        ResetConfirmed := TRUE;

        (* 确认不产生启动；终止可能尚未结束的停机保持。 *)
        DriveA_Run := FALSE;
        DriveB_Run := FALSE;
        BStopPending := FALSE;
        BDelayScans := UINT#0;
    END_IF;

    IF NOT ResetConfirmed THEN
        DriveA_Run := FALSE;
        IF NOT BStopPending THEN
            DriveB_Run := FALSE;
        END_IF;
    END_IF;
END_IF;

(* 最终安全覆盖：任何路径均不能保留 A 区危险运行。 *)
IF DoorSwitch OR NOT EStop_NC THEN
    DriveA_Run := FALSE;
END_IF;

AlarmLamp := DoorSwitch OR NOT EStop_NC;

IF NOT EStop_NC THEN
    Status := WORD#16#8303;
ELSIF DoorSwitch THEN
    Status := WORD#16#8302;
ELSIF NOT ResetConfirmed THEN
    Status := WORD#16#8301;
ELSE
    Status := WORD#16#0000;
END_IF;

(* 无条件更新边沿历史，避免危险期间按住复位在恢复时被当作新沿。 *)
PreviousDoor := DoorSwitch;
PreviousReset := ResetBtn;

END_FUNCTION_BLOCK
